//! Scene-linear exposure evidence, not inferred mastering or automatic grading.
use crate::effects::Frame;
use serde_json::{json,Value};
pub fn analyze(f:&Frame,gamut:usize,white:f64,gray:f64,peak:f64)->Result<Value,String>{
 if gamut>7||!white.is_finite()||!(1. ..=10000.).contains(&white)||!gray.is_finite()||!(1e-6 ..=100.).contains(&gray)||!peak.is_finite()||!(1. ..=100000.).contains(&peak)||f.w.checked_mul(f.h).and_then(|n|n.checked_mul(4))!=Some(f.d.len()){return Err("invalid exposure domain/frame".into())}
 let weights=super::managed::luma_weights(gamut);let capacity=f.d.len()/4;crate::guard::reserve(capacity.checked_mul(std::mem::size_of::<f64>()).ok_or("exposure allocation overflow")?);let mut ys=Vec::with_capacity(capacity);let mut invalid=0u64;let mut transparent=0u64;let mut negative_rgb=0u64;let mut above_peak_rgb=0u64;let mut nonpositive=0u64;let mut bins=[0u64;64];let mut low=0u64;let mut high=0u64;let mut alpha_sum=0.;let mut weighted=0.;
 for(i,p)in f.d.chunks_exact(4).enumerate(){if i%65536==0{crate::guard::check()}if p.iter().any(|v|!v.is_finite())||!(0. ..=1.).contains(&p[3]){invalid+=1;continue}if p[3]==0.{transparent+=1;continue}let y=weights.iter().zip(&p[..3]).map(|(w,v)|w* *v as f64).sum::<f64>();ys.push(y);alpha_sum+=p[3] as f64;weighted+=y*p[3] as f64;if p[..3].iter().any(|v|*v<0.){negative_rgb+=1}if p[..3].iter().any(|v|*v as f64*white>peak){above_peak_rgb+=1}if y<=0.{nonpositive+=1;continue}let stop=(y/gray).log2();if stop< -16.{low+=1}else if stop>=16.{high+=1}else{bins[((stop+16.)*2.).floor() as usize]+=1}}
 crate::guard::check();ys.sort_unstable_by(f64::total_cmp);crate::guard::check();let quantile=|q:f64|->Option<f64>{if ys.is_empty(){None}else{let x=q*(ys.len()-1) as f64;let i=x.floor() as usize;let j=(i+1).min(ys.len()-1);Some(ys[i]+(ys[j]-ys[i])*(x-i as f64))}};let ps=[0.,0.001,0.01,0.1,0.5,0.9,0.99,0.999,1.];let luminance:Vec<_>=ps.iter().map(|q|quantile(*q)).collect();let nits:Vec<_>=luminance.iter().map(|v|v.map(|x|x*white)).collect();let stops:Vec<_>=luminance.iter().map(|v|v.and_then(|x|if x>0.{Some((x/gray).log2())}else{None})).collect();
 Ok(json!({"domain":"working_scene_linear","gamut_id":gamut,"luminance_weights":weights,"reference_white_nits":white,"middle_gray":gray,"declared_peak_nits":peak,"visible_pixels":ys.len(),"invalid_pixels":invalid,"transparent_pixels":transparent,"negative_rgb_pixels":negative_rgb,"above_declared_peak_rgb_pixels":above_peak_rgb,"nonpositive_luminance_pixels":nonpositive,"quantile_fractions":ps,"quantile_method":"linear interpolation at q*(N-1), unweighted visible pixels","luminance_quantiles":luminance,"declared_nits_quantiles":nits,"stops_from_gray_quantiles":stops,"alpha_weighted_mean_luminance":if alpha_sum>0.{Some(weighted/alpha_sum)}else{None},"stop_histogram":bins.to_vec(),"stop_range":[-16,16],"stop_bin_width":0.5,"stop_under_range":low,"stop_over_range":high,"note":"Nits scale is caller-declared reference white, not measured mastering. RGB peak excursions are not proof of clipping. No suggested exposure change without a creative target."}))
}
/// Explicit analytical stop palette. Not a camera's proprietary false-color scale.
pub fn false_color(f:&Frame,gamut:usize,gray:f64)->Result<Frame,String>{
 if gamut>7||!gray.is_finite()||!(1e-6 ..=100.).contains(&gray)||f.w.checked_mul(f.h).and_then(|n|n.checked_mul(4))!=Some(f.d.len()){return Err("invalid false-color domain".into())}
 let weights=super::managed::luma_weights(gamut);let mut out=Frame::new(f.w,f.h);for(i,p)in f.d.chunks_exact(4).enumerate(){if i%65536==0{crate::guard::check()}let color=if p.iter().any(|v|!v.is_finite())||!(0. ..=1.).contains(&p[3]){[1.,0.,1.]}else if p[3]==0.{[0.,0.,0.]}else{let y=weights.iter().zip(&p[..3]).map(|(w,v)|w* *v as f64).sum::<f64>();if y<=0.{[0.1,0.,0.2]}else{let stops=(y/gray).log2();match stops{v if v< -6.=>[0.,0.,0.35],v if v< -3.=>[0.,0.25,1.],v if v< -1.=>[0.,0.8,1.],v if v<1.=>[0.1,0.65,0.1],v if v<3.=>[1.,0.85,0.],v if v<6.=>[1.,0.3,0.],_=>[1.,0.,0.]}}};out.d[i*4..i*4+3].copy_from_slice(&color);out.d[i*4+3]=1.;}Ok(out)
}
pub fn legend()->serde_json::Value{json!({"scale":"stops relative to caller middle gray","bands":[{"range":"nonpositiveY","rgb":[0.1,0.,0.2]},{"range":"below-6","rgb":[0.,0.,0.35]},{"range":"-6..-3","rgb":[0.,0.25,1.]},{"range":"-3..-1","rgb":[0.,0.8,1.]},{"range":"-1..1","rgb":[0.1,0.65,0.1]},{"range":"1..3","rgb":[1.,0.85,0.]},{"range":"3..6","rgb":[1.,0.3,0.]},{"range":"6+","rgb":[1.,0.,0.]}],"invalid":"magenta","transparent":"black","note":"Analytical palette, not ARRI/RED/industry-standard false-color calibration"})}
/// Reference-relative exposure suggestion only, not semantic shot matching.
pub fn compare(source:&Frame,reference:&Frame,gamut:usize,white:f64,percentile:f64)->Result<Value,String>{
 if !percentile.is_finite()||!(0.1..=0.9).contains(&percentile){return Err("match percentile0.1..0.9 required".into())}
 let statistic=|f:&Frame|->Result<(f64,usize),String>{if f.w==0||f.h==0||f.w.checked_mul(f.h).and_then(|n|n.checked_mul(4))!=Some(f.d.len())||gamut>7||!white.is_finite()||!(1. ..=10000.).contains(&white){return Err("invalid exposure comparison frame/domain".into())}let weights=super::managed::luma_weights(gamut);let capacity=f.d.len()/4;crate::guard::reserve(capacity.checked_mul(std::mem::size_of::<f64>()).ok_or("exposure comparison allocation overflow")?);let mut values=Vec::with_capacity(capacity);for(i,p)in f.d.chunks_exact(4).enumerate(){if i%65536==0{crate::guard::check()}if p.iter().any(|v|!v.is_finite())||p[3]<0.99||p[3]>1.{continue}let y=weights.iter().zip(&p[..3]).map(|(w,v)|w* *v as f64).sum::<f64>();if y>1e-8{values.push(y)}}if values.len()<4{return Err("exposure comparison needs4positive opaque pixels perframe".into())}crate::guard::check();values.sort_unstable_by(f64::total_cmp);crate::guard::check();let x=percentile*(values.len()-1) as f64;let i=x.floor() as usize;let j=(i+1).min(values.len()-1);Ok((values[i]+(values[j]-values[i])*(x-i as f64),values.len()))};
 let (s,sn)=statistic(source)?;let(r,rn)=statistic(reference)?;let delta=(r/s).log2();if !delta.is_finite()||delta.abs()>20.{return Err("exposure suggestion exceeds linear_grade20stop bound".into())}
 Ok(json!({"working_gamut":gamut,"percentile":percentile,"source_positive_opaque_samples":sn,"reference_positive_opaque_samples":rn,"source_luminance_statistic":s,"reference_luminance_statistic":r,"suggested_exposure_stops":delta,"suggested_linear_grade_params":{"exposure":delta},"reference_white_nits":white,"effect_applied":false,"note":"Reference-relative positive opaque luminance percentile only. Different framing, subjects, clipping and illumination may make this an unsuitable creative target. No semantic match, color cast correction, calibrated measurement or automatic mutation."}))
}
